public class WordCounterCheckerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object verdict(WordCounter impl) {
        try {
            return WordCounterChecker.isCorrect(impl);
        } catch (Throwable crash) {
            return "isCorrect threw " + crash.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("accepts the correct implementation", true, verdict(new CorrectCounter()));
        check("accepts an equally correct implementation", true, verdict(new AlsoCorrectCounter()));
        check("rejects the version that treats Cat and cat as different words", false, verdict(new CaseSensitiveCounter()));
        check("rejects the version that never counts past one", false, verdict(new AlwaysOneCounter()));
        check("rejects the null returned instead of an empty map", false, verdict(new NullOnEmptyCounter()));
        check("rejects the version that empties the caller's list", false, verdict(new DestructiveCounter()));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

class CorrectCounter implements WordCounter {
    public java.util.Map<String, Integer> count(java.util.List<String> words) {
        java.util.Map<String, Integer> counts = new java.util.HashMap<>();
        for (String word : words) {
            counts.merge(word.toLowerCase(), 1, Integer::sum);
        }
        return counts;
    }
}

class AlsoCorrectCounter implements WordCounter {
    public java.util.Map<String, Integer> count(java.util.List<String> words) {
        java.util.Map<String, Integer> counts = new java.util.TreeMap<>();
        for (int i = 0; i < words.size(); i++) {
            String key = words.get(i).toLowerCase();
            Integer seen = counts.get(key);
            counts.put(key, seen == null ? 1 : seen + 1);
        }
        return counts;
    }
}

class CaseSensitiveCounter implements WordCounter {
    public java.util.Map<String, Integer> count(java.util.List<String> words) {
        java.util.Map<String, Integer> counts = new java.util.HashMap<>();
        for (String word : words) {
            counts.merge(word, 1, Integer::sum);
        }
        return counts;
    }
}

class AlwaysOneCounter implements WordCounter {
    public java.util.Map<String, Integer> count(java.util.List<String> words) {
        java.util.Map<String, Integer> counts = new java.util.HashMap<>();
        for (String word : words) {
            counts.put(word.toLowerCase(), 1);
        }
        return counts;
    }
}

class NullOnEmptyCounter implements WordCounter {
    public java.util.Map<String, Integer> count(java.util.List<String> words) {
        if (words.isEmpty()) return null;
        java.util.Map<String, Integer> counts = new java.util.HashMap<>();
        for (String word : words) {
            counts.merge(word.toLowerCase(), 1, Integer::sum);
        }
        return counts;
    }
}

class DestructiveCounter implements WordCounter {
    public java.util.Map<String, Integer> count(java.util.List<String> words) {
        java.util.Map<String, Integer> counts = new java.util.HashMap<>();
        while (!words.isEmpty()) {
            counts.merge(words.remove(0).toLowerCase(), 1, Integer::sum);
        }
        return counts;
    }
}

