/**
 * TASK: Write the checks that decide whether a WordCounter is correct.
 *
 *   count(words) returns how many times each word appears, ignoring case.
 *   Keys in the returned map are lower-case. An empty list gives an empty map
 *   (never null). The list passed in must not be modified.
 *   Example: count(["Cat", "dog", "cat"]) -> {cat=2, dog=1}
 *
 * isCorrect(impl) must return true for an implementation that honours the
 * contract and false for one that does not. Some broken implementations THROW
 * instead of returning a value, so a crash counts as a failure: wrap your calls
 * in try/catch and return false if anything is thrown.
 *
 * One happy-path call is not a test suite. Choose inputs that expose specific
 * bugs, including the boundary cases named in the contract.
 */
import java.util.List;
import java.util.Map;

interface WordCounter {
    /* Provided -- do not edit. */
    Map<String, Integer> count(List<String> words);
}

public class WordCounterChecker {

    public static boolean isCorrect(WordCounter impl) {
        try {
            java.util.Map<String, Integer> mixed =
                    impl.count(java.util.List.of("Cat", "dog", "cat"));
            if (mixed == null) return false;
            if (mixed.size() != 2) return false;
            if (!Integer.valueOf(2).equals(mixed.get("cat"))) return false;
            if (!Integer.valueOf(1).equals(mixed.get("dog"))) return false;

            java.util.Map<String, Integer> empty = impl.count(java.util.List.of());
            if (empty == null || !empty.isEmpty()) return false;

            java.util.List<String> original =
                    new java.util.ArrayList<>(java.util.List.of("a", "b"));
            impl.count(original);
            if (original.size() != 2) return false;
        } catch (Throwable crash) {
            return false;
        }
        return true;
    }
}
